3	namespace App\Services\Media;
4	
5	use App\Models\Core\MediaVariant;
6	use Illuminate\Http\UploadedFile;
7	use Illuminate\Support\Facades\Log;
8	use Illuminate\Support\Facades\Storage;
9	
10	/**
11	 * Generates universal WebP image variants from an uploaded original and
12	 * persists them to the configured media disk (S3-compatible / R2).
13	 *
14	 * Every image (gallery or content) gets the same configured variant set.
15	 * Current default produces two full-resolution variants:
16	 * - optimized (target-size adaptive quality)
17	 * - maximized (highest quality)
18	 *
19	 * Requires the GD extension with WebP support (ships with PHP 8.2+).
20	 */
21	// V2: Generates WebP image variants from uploads via GD. Content-hashed storage on Cloudflare R2 with adaptive quality targeting.
22	class ImageVariantService
23	{
24	    private const ALLOWED_IMAGE_MIMES = ['image/jpeg', 'image/png', 'image/webp'];
25	
26	    /** Safe extensions for R2 object keys — anything else falls back to the canonical default. */
27	    private const ALLOWED_EXTENSIONS = ['jpg', 'jpeg', 'png', 'webp', 'mp4', 'mov', 'webm'];
28	
29	    /* ------------------------------------------------------------------ */
30	    /*  Public API */
31	    /* ------------------------------------------------------------------ */
32	
33	    /**
34	     * Process an original image into all configured variants, store them
35	     * on the media disk, and persist ImageVariant rows for the given image.
36	     *
37	     * @param  string  $originalTmpPath  Absolute path to the temp original.
38	     * @param  string  $imageId  UUID of the SiteMedia row.
39	     * @param  string  $basePath  e.g. "images/<proId>/<imageId>"
40	     * @return array<string, MediaVariant> keyed by variant name
41	     */
42	    public function processVariants(
43	        string $originalTmpPath,
44	        string $imageId,
45	        string $basePath,
46	    ): array {
47	        // Ensure GD extension is available with WebP support
48	        if (! extension_loaded('gd')) {
49	            throw new \RuntimeException('GD extension is not loaded. Cannot process image variants.');
50	        }
51	
52	        if (! function_exists('imagewebp')) {
53	            throw new \RuntimeException('GD WebP support is not available. Cannot generate WebP variants.');
54	        }
55	
56	        \Illuminate\Support\Facades\Log::info('Starting image variant processing', [
57	            'image_id' => $imageId,
58	            'base_path' => $basePath,
59	        ]);
60	
61	        $disk = $this->disk();
62	        $definitions = $this->variantDefinitions();
63	
64	        $sourceImage = $this->loadImage($originalTmpPath);
65	
66	        if (! $sourceImage) {
67	            throw new \RuntimeException('Failed to create GD image from the uploaded file.');
68	        }
69	
70	        $sourceWidth = imagesx($sourceImage);
71	        $sourceHeight = imagesy($sourceImage);
72	
73	        $created = [];
74	
75	        try {
76	            foreach ($definitions as $variantName => $def) {
77	                $quality = max(1, min(100, (int) ($def['quality'] ?? 92)));
78	                $minQuality = max(1, min($quality, (int) ($def['min_quality'] ?? 60)));
79	                $targetKb = max(0, (int) ($def['target_kb'] ?? 0));
80	                $targetBytes = $targetKb > 0 ? ($targetKb * 1024) : null;
81	                $fit = (string) ($def['fit'] ?? 'inside');
82	
83	                $preserveResolution = filter_var(
84	                    $def['preserve_resolution'] ?? false,
85	                    FILTER_VALIDATE_BOOLEAN,
86	                    FILTER_NULL_ON_FAILURE,
87	                );
88	                $preserveResolution = $preserveResolution ?? false;
89	
90	                if ($preserveResolution) {
91	                    [$cropX, $cropY, $cropW, $cropH, $dstW, $dstH] = [0, 0, $sourceWidth, $sourceHeight, $sourceWidth, $sourceHeight];
92	                } else {
93	                    $targetW = max(1, (int) ($def['width'] ?? $sourceWidth));
94	                    $targetH = max(1, (int) ($def['height'] ?? $sourceHeight));
95	
96	                    // Backward-compatible path for capped variants.
97	                    [$cropX, $cropY, $cropW, $cropH, $dstW, $dstH] = $this->calculateDimensions(
98	                        $sourceWidth, $sourceHeight, $targetW, $targetH, $fit,
99	                    );
100	                }
101	
102	                $canvas = imagecreatetruecolor($dstW, $dstH);
103	                imagealphablending($canvas, false);
104	                imagesavealpha($canvas, true);
105	
106	                imagecopyresampled(
107	                    $canvas, $sourceImage,
108	                    0, 0, $cropX, $cropY,
109	                    $dstW, $dstH, $cropW, $cropH,
110	                );
111	
112	                // --- Encode to WebP ---
113	                $tmpFile = tempnam(sys_get_temp_dir(), 'sidest_img_');
114	                if (! is_string($tmpFile) || $tmpFile === '') {
115	                    throw new \RuntimeException('Failed to create temp file for WebP encoding.');
116	                }
117	
118	                try {
119	                    $encodedQuality = $quality;
120	                    if ($targetBytes !== null) {
121	                        $encodedQuality = $this->encodeWebpToTargetSize(
122	                            image: $canvas,
123	                            tmpFile: $tmpFile,
124	                            maxQuality: $quality,
125	                            minQuality: $minQuality,
126	                            targetBytes: $targetBytes,
127	                        );
128	                    } else {
129	                        $this->encodeWebp($canvas, $tmpFile, $quality);
130	                    }
131	
132	                    $fileBytes = filesize($tmpFile);
133	                    if ($fileBytes === false) {
134	                        throw new \RuntimeException('Failed to determine encoded WebP file size.');
135	                    }
136	
137	                    if ($targetBytes !== null && $fileBytes > $targetBytes) {
138	                        Log::warning('Image variant exceeded target size at min quality.', [
139	                            'image_id' => $imageId,
140	                            'variant' => $variantName,
141	                            'target_kb' => $targetKb,
142	                            'actual_kb' => (int) round($fileBytes / 1024),
143	                            'quality_used' => $encodedQuality,
144	                        ]);
145	                    }
146	
147	                    $hash = hash_file('sha256', $tmpFile);
148	                    if (! is_string($hash)) {
149	                        throw new \RuntimeException('Failed to hash encoded WebP variant.');
150	                    }
151	                    $hash = substr($hash, 0, 16);
152	
153	                    // Content-hashed filename: optimized_abc123def456.webp
154	                    $storagePath = "{$basePath}/{$variantName}_{$hash}.webp";
155	
156	                    // --- Upload to bucket ---
157	                    $payload = file_get_contents($tmpFile);
158	                    if ($payload === false) {
159	                        throw new \RuntimeException('Failed to read encoded WebP for upload.');
160	                    }
161	                    $disk->put($storagePath, $payload, 'public');
162	
163	                    // --- Upsert DB row ---
164	                    $variant = MediaVariant::updateOrCreate(
165	                        [
166	                            'media_id' => $imageId,
167	                            'variant_key' => $variantName,
168	                            'artifact_type' => 'webp',
169	                        ],
170	                        [
171	                            'disk' => $this->diskName(),
172	                            'path' => $storagePath,
173	                            'mime' => 'image/webp',
174	                            'width' => $dstW,
175	                            'height' => $dstH,
176	                            'file_size_bytes' => $fileBytes,
177	                            'content_hash' => $hash,
178	                        ],
179	                    );
180	
181	                    $created[$variantName] = $variant;
182	                } finally {
183	                    @unlink($tmpFile);
184	                    unset($canvas);
185	                }
186	            }
187	        } finally {
188	            unset($sourceImage);
189	        }
190	
191	        \Illuminate\Support\Facades\Log::info('Image variant processing completed', [
192	            'image_id' => $imageId,
193	            'variant_count' => count($created),
194	        ]);
195	
196	        return $created;
197	    }
198	
199	    /**
200	     * Normalize a client-supplied extension against the allowlist.
201	     * Falls back to $default if the value is empty or not on the list.
202	     */
203	    public function safeExtension(string $clientExt, string $default = 'jpg'): string
204	    {
205	        $normalized = strtolower(ltrim($clientExt, '.'));
206	
207	        return in_array($normalized, self::ALLOWED_EXTENSIONS, true) ? $normalized : $default;
208	    }
209	
210	    /**
211	     * Store the original upload to a location on the media disk
212	     * (kept for disaster-recovery / re-processing).
213	     *
214	     * Returns the storage path of the original.
215	     */
216	    public function storeOriginal(UploadedFile $file, string $basePath): string
217	    {
218	        $ext = $this->safeExtension($file->getClientOriginalExtension() ?? '', 'jpg');
219	        $hash = substr(hash_file('sha256', $file->getRealPath()), 0, 16);
220	        $path = "{$basePath}/original_{$hash}.{$ext}";
221	
222	        $this->disk()->put($path, file_get_contents($file->getRealPath()), 'public');
223	
224	        return $path;
225	    }
226	
227	    /**
228	     * Delete all image variant files (and DB rows) for a given SiteMedia item,
229	     * plus the original file stored at the image's path.
230	     */
231	    public function deleteVariants(string $imageId, ?string $originalPath = null): void
232	    {
233	        $variants = MediaVariant::where('media_id', $imageId)
234	            ->where('artifact_type', 'webp')
235	            ->get();
236	        $disk = $this->disk();
237	
238	        foreach ($variants as $variant) {
239	            $disk->delete($variant->path);
240	            $variant->delete();
241	        }
242	
243	        // Also remove the original if a path was provided
244	        if ($originalPath && $disk->exists($originalPath)) {
245	            $disk->delete($originalPath);
246	        }
247	    }
248	
249	    /**
250	     * Build a variant map (variant_key → public URL) for a SiteMedia image item.
251	     *
252	     * @return array<string, string>
253	     */
254	    public function variantUrls(string $imageId): array
255	    {
256	        return MediaVariant::where('media_id', $imageId)
257	            ->where('artifact_type', 'webp')
258	            ->get()
259	            ->mapWithKeys(fn (MediaVariant $v) => [$v->variant_key => $v->url])
260	            ->all();
261	    }
262	
263	    /**
264	     * Resolve the effective media disk name used for all reads/writes.
265	     */
266	    public function resolvedDiskName(): string
267	    {
268	        return $this->diskName();
269	    }
270	
271	    /* ------------------------------------------------------------------ */
272	    /*  Internal helpers */
273	    /* ------------------------------------------------------------------ */
274	
275	    private function diskName(): string
276	    {
277	        $configured = (string) config('partna.media_disk', 'media');
278	
279	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
280	        // but injects platform env vars directly into the process environment at runtime,
281	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
282	        $explicit = $_ENV['PARTNA_MEDIA_DISK'] ?? $_SERVER['PARTNA_MEDIA_DISK']
283	            ?? $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
284	        if (is_string($explicit) && trim($explicit) !== '') {
285	            return $configured;
286	        }
287	
288	        // Laravel Cloud injects disks dynamically and may set a non-"media"
289	        // filesystems.default disk. If media disk is only a fallback value,
290	        // prefer the Cloud default to avoid missing/empty media credentials.
291	        if ($configured === 'media') {
292	            $default = (string) config('filesystems.default', 'local');
293	            $defaultConfig = config("filesystems.disks.{$default}");
294	
295	            if (
296	                $default !== '' &&
297	                $default !== 'local' &&
298	                $default !== 'media' &&
299	                is_array($defaultConfig) &&
300	                (($defaultConfig['driver'] ?? null) === 's3')
301	            ) {
302	                Log::warning('PARTNA_MEDIA_DISK not set (legacy fallback: SIDEST_MEDIA_DISK); using filesystems.default disk for media operations.', [
303	                    'configured_media_disk' => $configured,
304	                    'fallback_disk' => $default,
305	                ]);
306	
307	                return $default;
308	            }
309	        }
310	
311	        return $configured;
312	    }
313	
314	    private function disk(): \Illuminate\Contracts\Filesystem\Filesystem
315	    {
316	        return Storage::disk($this->diskName());
317	    }
318	
319	    /**
320	     * Universal variant definitions (same for all images).
321	     */
322	    private function variantDefinitions(): array
323	    {
324	        $definitions = (array) config('partna.image_variants', []);
325	
326	        if ($definitions !== []) {
327	            return $definitions;
328	        }
329	
330	        // NOTE: this fallback MUST mirror config/partna.php image_variants exactly.
331	        // It runs only when config is empty (sparse test environments).
332	        return [
333	            'optimized' => [
334	                'format' => 'webp',
335	                'width' => 2400,
336	                'height' => 2400,
337	                'fit' => 'inside',
338	                'quality' => 92,
339	                'min_quality' => 60,
340	                'target_kb' => 500,
341	            ],
342	            'maximized' => [
343	                'format' => 'webp',
344	                'width' => 4000,
345	                'height' => 4000,
346	                'fit' => 'inside',
347	                'quality' => 92,
348	            ],
349	        ];
350	    }
