352	    /**
353	     * Load an image file into a GD resource regardless of source format.
354	     *
355	     * Refuses images whose pixel count exceeds partna.image_max_pixels by
356	     * throwing UnprocessableImageException BEFORE any bitmap memory is
357	     * allocated. This is the defense against image-bomb uploads — a tiny
358	     * JPEG/PNG file can decode to a huge bitmap (4 bytes per pixel), which
359	     * the worker cannot survive even with the canvas caps applied.
360	     *
361	     * The getimagesize() call reads only the file header (a few KB), not
362	     * the pixel data, so the guard is effectively free.
363	     */
364	    private function loadImage(string $path): \GdImage|false
365	    {
366	        // Sniff actual bytes before getimagesize — prevents a crafted file from
367	        // claiming a safe format while hiding a decompression bomb in its content stream.
368	        $actualMime = (new \finfo(FILEINFO_MIME_TYPE))->file($path);
369	        if (! in_array($actualMime, self::ALLOWED_IMAGE_MIMES, true)) {
370	            throw new UnprocessableImageException(
371	                "Rejected: MIME type '{$actualMime}' is not an accepted image format."
372	            );
373	        }
374	
375	        $info = @getimagesize($path);
376	        if (! $info) {
377	            return false;
378	        }
379	
380	        $width = (int) $info[0];
381	        $height = (int) $info[1];
382	        $maxPixels = (int) config('partna.image_max_pixels', 24_000_000);
383	
384	        if ($width * $height > $maxPixels) {
385	            throw new UnprocessableImageException(sprintf(
386	                'Image dimensions exceed safe processing limit (%d x %d = %d pixels, max %d).',
387	                $width,
388	                $height,
389	                $width * $height,
390	                $maxPixels,
391	            ));
392	        }
393	
394	        return match ($info[2]) {
395	            IMAGETYPE_JPEG => @imagecreatefromjpeg($path),
396	            IMAGETYPE_PNG => @imagecreatefrompng($path),
397	            IMAGETYPE_WEBP => @imagecreatefromwebp($path),
398	            default => false,
399	        };
400	    }
401	
402	    /**
403	     * Encode an image as WebP at the given quality and return file size.
404	     */
405	    private function encodeWebp(\GdImage $image, string $tmpFile, int $quality): int
406	    {
407	        if (@imagewebp($image, $tmpFile, $quality) === false) {
408	            throw new \RuntimeException("Failed to encode WebP at quality {$quality}.");
409	        }
410	
411	        clearstatcache(true, $tmpFile);
412	        $size = filesize($tmpFile);
413	        if ($size === false) {
414	            throw new \RuntimeException('Failed to read encoded WebP size.');
415	        }
416	
417	        return $size;
418	    }
419	
420	    /**
421	     * Binary-search the highest quality that stays under target bytes.
422	     *
423	     * Returns the quality used for the final file in $tmpFile.
424	     */
425	    private function encodeWebpToTargetSize(
426	        \GdImage $image,
427	        string $tmpFile,
428	        int $maxQuality,
429	        int $minQuality,
430	        int $targetBytes,
431	    ): int {
432	        $lower = max(1, min(100, $minQuality));
433	        $upper = max($lower, min(100, $maxQuality));
434	
435	        $bestQuality = null;
436	
437	        while ($lower <= $upper) {
438	            $mid = intdiv($lower + $upper, 2);
439	            $size = $this->encodeWebp($image, $tmpFile, $mid);
440	
441	            if ($size <= $targetBytes) {
442	                $bestQuality = $mid;
443	                $lower = $mid + 1;
444	
445	                continue;
446	            }
447	
448	            $upper = $mid - 1;
449	        }
450	
451	        if ($bestQuality !== null) {
452	            $this->encodeWebp($image, $tmpFile, $bestQuality);
453	
454	            return $bestQuality;
455	        }
456	
457	        // Could not satisfy target even at min quality.
458	        $this->encodeWebp($image, $tmpFile, max(1, min(100, $minQuality)));
459	
460	        return max(1, min(100, $minQuality));
461	    }
462	
463	    /**
464	     * Calculate crop / resize geometry.
465	     *
466	     * @return array [cropX, cropY, cropW, cropH, dstW, dstH]
467	     */
468	    private function calculateDimensions(
469	        int $srcW, int $srcH,
470	        int $maxW, int $maxH,
471	        string $fit,
472	    ): array {
473	        if ($fit === 'cover') {
474	            $srcRatio = $srcW / $srcH;
475	            $dstRatio = $maxW / $maxH;
476	
477	            if ($srcRatio > $dstRatio) {
478	                $cropH = $srcH;
479	                $cropW = (int) round($srcH * $dstRatio);
480	                $cropX = (int) round(($srcW - $cropW) / 2);
481	                $cropY = 0;
482	            } else {
483	                $cropW = $srcW;
484	                $cropH = (int) round($srcW / $dstRatio);
485	                $cropX = 0;
486	                $cropY = (int) round(($srcH - $cropH) / 2);
487	            }
488	
489	            return [$cropX, $cropY, $cropW, $cropH, $maxW, $maxH];
490	        }
491	
492	        // "inside" – fit within bounds, no crop, never upscale
493	        $ratio = min($maxW / $srcW, $maxH / $srcH, 1);
494	        $dstW = (int) round($srcW * $ratio);
495	        $dstH = (int) round($srcH * $ratio);
496	
497	        return [0, 0, $srcW, $srcH, $dstW, $dstH];
498	    }
499	}
