11	/**
12	 * Transcodes a video original into MP4 + HLS variants and a poster image,
13	 * stores all artifacts on the media disk, and persists MediaVariant rows.
14	 *
15	 * Processing order (avoids extra re-encodes):
16	 *   1. FFprobe  – extract metadata + validate duration
17	 *   2. FFmpeg   – encode optimized MP4 (720p)
18	 *   3. FFmpeg   – encode maximized MP4 (1080p)
19	 *   4. FFmpeg   – package HLS segments from each MP4 (stream-copy, no re-encode)
20	 *   5. Build    – write master adaptive HLS playlist
21	 *   6. FFmpeg   – extract poster JPEG at 1s mark
22	 *   7. Upload   – stream all artifacts to media disk
23	 *   8. DB upsert – persist one MediaVariant row per logical artifact
24	 *   9. SiteMedia update – set processing_state, duration_ms, poster_path
25	 *
26	 * Storage layout under the media disk:
27	 *   videos/{proId}/{mediaId}/
28	 *     original_{hash}.{ext}
29	 *     optimized.mp4
30	 *     maximized.mp4
31	 *     hls/
32	 *       optimized/playlist.m3u8  + seg_*.ts
33	 *       maximized/playlist.m3u8  + seg_*.ts
34	 *       adaptive.m3u8             (master playlist)
35	 *     poster.jpg
36	 *
37	 * Requires ffmpeg and ffprobe to be available (configured via config/partna.php).
38	 */
39	// V2: Transcodes videos to MP4 + HLS via FFmpeg. Feature-flagged (PARTNA_VIDEO_UPLOADS_ENABLED). Uses dedicated redis_video connection.
40	class VideoVariantService
41	{
42	    /** Codecs we will transcode. hevc = H.265 (ffprobe reports 'hevc', not 'h265'). */
43	    private const ALLOWED_CODECS = ['h264', 'hevc', 'vp9'];
44	
45	    /** 4K ceiling: long edge ≤ 3840px, short edge ≤ 2160px. */
46	    private const MAX_RESOLUTION_LONG = 3840;
47	
48	    private const MAX_RESOLUTION_SHORT = 2160;
49	
50	    /* ------------------------------------------------------------------ */
51	    /*  Public API */
52	    /* ------------------------------------------------------------------ */
53	
54	    /**
55	     * Run FFprobe on a local file and return metadata array.
56	     * Throws \RuntimeException if the binary fails.
57	     *
58	     * @return array<string, mixed>
59	     */
60	    public function probe(string $localPath): array
61	    {
62	        $ffprobe = $this->ffprobeBinary();
63	
64	        // Array-form Process: each element is a literal argument; no shell interpolation.
65	        $process = new Process([
66	            $ffprobe, '-v', 'quiet', '-print_format', 'json',
67	            '-show_format', '-show_streams', $localPath,
68	        ]);
69	        $process->setTimeout(30);
70	        $process->run();
71	
72	        if (! $process->isSuccessful()) {
73	            $exitCode = $process->getExitCode();
74	            $err = $process->getErrorOutput() ?: $process->getOutput();
75	            throw new \RuntimeException("ffprobe failed (exit {$exitCode}): {$err}");
76	        }
77	
78	        $data = json_decode($process->getOutput(), true);
79	        if (! is_array($data)) {
80	            throw new \RuntimeException('ffprobe returned non-JSON output.');
81	        }
82	
83	        return $data;
84	    }
85	
86	    /**
87	     * Probe a local file and validate it contains at least one video stream
88	     * and does not exceed the configured maximum duration.
89	     *
90	     * Call this in the upload controller before storing to R2 so malformed
91	     * containers and over-length videos are rejected at the HTTP boundary,
92	     * not on the worker.
93	     *
94	     * @return array<string, mixed> Raw ffprobe data (reuse to avoid a second probe).
95	     *
96	     * @throws \RuntimeException if the container is unreadable, has no video stream, or exceeds max duration.
97	     */
98	    public function probeAndValidate(string $localPath): array
99	    {
100	        $probe = $this->probe($localPath);
101	
102	        $videoStream = null;
103	        foreach ($probe['streams'] ?? [] as $stream) {
104	            if (($stream['codec_type'] ?? '') === 'video') {
105	                $videoStream = $stream;
106	                break;
107	            }
108	        }
109	
110	        if ($videoStream === null) {
111	            throw new \RuntimeException('File does not contain a recognisable video stream.');
112	        }
113	
114	        $codec = strtolower((string) ($videoStream['codec_name'] ?? ''));
115	        if (! in_array($codec, self::ALLOWED_CODECS, true)) {
116	            throw new \RuntimeException(
117	                "Unsupported video codec '{$codec}'. Allowed: ".implode(', ', self::ALLOWED_CODECS).'.'
118	            );
119	        }
120	
121	        $width = (int) ($videoStream['width'] ?? 0);
122	        $height = (int) ($videoStream['height'] ?? 0);
123	        $longEdge = max($width, $height);
124	        $shortEdge = min($width, $height);
125	        if ($longEdge > self::MAX_RESOLUTION_LONG || $shortEdge > self::MAX_RESOLUTION_SHORT) {
126	            throw new \RuntimeException(
127	                "Video resolution {$width}×{$height} exceeds the maximum allowed (3840×2160 / 4K)."
128	            );
129	        }
130	
131	        $durationMs = $this->extractDurationMs($probe);
132	        $maxDurSec = (int) config('partna.video_max_duration_seconds', 300);
133	
134	        if ($durationMs > $maxDurSec * 1000) {
135	            $actualSec = (int) round($durationMs / 1000);
136	            throw new \RuntimeException(
137	                "Video is too long ({$actualSec}s). Maximum allowed duration is {$maxDurSec}s."
138	            );
139	        }
140	
141	        return $probe;
142	    }
