144	    /**
145	     * Process a video original into all configured artifacts.
146	     *
147	     * @throws \RuntimeException on unrecoverable processing errors
148	     */
149	    public function processVariants(
150	        string $localOriginalPath,
151	        string $mediaId,
152	        string $basePath,
153	    ): void {
154	        Log::info('VideoVariantService: starting', [
155	            'media_id' => $mediaId,
156	            'base_path' => $basePath,
157	        ]);
158	
159	        // --- 1. Probe metadata + validate codec, resolution, and duration ---
160	        $probe = $this->probeAndValidate($localOriginalPath);
161	        $durationMs = $this->extractDurationMs($probe);
162	
163	        // Timeout budget: 2× video duration + 60s, floored at 120s for very short clips.
164	        $encodingTimeout = max(120, (int) round($durationMs / 1000) * 2 + 60);
165	
166	        $variantDefs = (array) config('partna.video_variants', []);
167	        $tmpDirs = [];
168	
169	        try {
170	            // --- 2 & 3. Encode MP4 variants ---
171	            $mp4Paths = [];
172	            foreach ($variantDefs as $variantKey => $def) {
173	                $tmpMp4 = $this->makeTmpFile("sidest_mp4_{$variantKey}_", '.mp4');
174	                $this->encodeMp4($localOriginalPath, $tmpMp4, $def, $encodingTimeout);
175	                $mp4Paths[$variantKey] = $tmpMp4;
176	            }
177	
178	            // --- 4. Package HLS from each MP4 ---
179	            $hlsDirs = [];
180	            foreach ($mp4Paths as $variantKey => $mp4) {
181	                $tmpHlsDir = sys_get_temp_dir().'/sidest_hls_'.$variantKey.'_'.uniqid();
182	                if (! mkdir($tmpHlsDir, 0755, true)) {
183	                    throw new \RuntimeException("Failed to create HLS temp dir: {$tmpHlsDir}");
184	                }
185	                $tmpDirs[] = $tmpHlsDir;
186	                $this->packageHls($mp4, $tmpHlsDir.'/playlist.m3u8', $encodingTimeout);
187	                $hlsDirs[$variantKey] = $tmpHlsDir;
188	            }
189	
190	            // --- 5. Build adaptive master playlist ---
191	            $adaptiveContent = $this->buildAdaptivePlaylist($variantDefs);
192	
193	            // --- 6. Extract poster ---
194	            $tmpPoster = $this->makeTmpFile('sidest_poster_', '.jpg');
195	            $this->extractPoster($localOriginalPath, $tmpPoster, $encodingTimeout);
196	
197	            // --- 7. Upload all artifacts ---
198	            $disk = $this->disk();
199	            $diskName = $this->resolvedDiskName();
200	
201	            // Upload MP4s
202	            foreach ($mp4Paths as $variantKey => $mp4) {
203	                $remotePath = "{$basePath}/{$variantKey}.mp4";
204	                $stream = fopen($mp4, 'rb');
205	                $disk->put($remotePath, $stream, 'public');
206	                if (is_resource($stream)) {
207	                    fclose($stream);
208	                }
209	
210	                $def = $variantDefs[$variantKey] ?? [];
211	                // Unique key: (media_id, variant_key, artifact_type)
212	                MediaVariant::updateOrCreate(
213	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'mp4'],
214	                    [
215	                        'disk' => $diskName,
216	                        'path' => $remotePath,
217	                        'mime' => 'video/mp4',
218	                        'bitrate_kbps' => (int) ($def['video_bitrate_kbps'] ?? 0) + (int) ($def['audio_bitrate_kbps'] ?? 0),
219	                        'file_size_bytes' => filesize($mp4) ?: null,
220	                        'duration_ms' => $durationMs,
221	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
222	                    ]
223	                );
224	            }
225	
226	            // Upload HLS segments + playlists
227	            foreach ($hlsDirs as $variantKey => $hlsDir) {
228	                $remoteHlsBase = "{$basePath}/hls/{$variantKey}";
229	                foreach (scandir($hlsDir) ?: [] as $file) {
230	                    if ($file === '.' || $file === '..') {
231	                        continue;
232	                    }
233	                    $localFile = "{$hlsDir}/{$file}";
234	                    $remotePath = "{$remoteHlsBase}/{$file}";
235	                    $mime = str_ends_with($file, '.m3u8') ? 'application/vnd.apple.mpegurl' : 'video/mp2t';
236	                    $stream = fopen($localFile, 'rb');
237	                    $disk->put($remotePath, $stream, ['visibility' => 'public', 'ContentType' => $mime]);
238	                    if (is_resource($stream)) {
239	                        fclose($stream);
240	                    }
241	                }
242	
243	                $playlistPath = "{$remoteHlsBase}/playlist.m3u8";
244	                $def = $variantDefs[$variantKey] ?? [];
245	                MediaVariant::updateOrCreate(
246	                    ['media_id' => $mediaId, 'variant_key' => $variantKey, 'artifact_type' => 'hls_playlist'],
247	                    [
248	                        'disk' => $diskName,
249	                        'path' => $playlistPath,
250	                        'mime' => 'application/vnd.apple.mpegurl',
251	                        'duration_ms' => $durationMs,
252	                        'metadata' => ['resolution' => $def['resolution'] ?? null],
253	                    ]
254	                );
255	            }
256	
257	            // Upload adaptive master playlist
258	            $adaptiveRemotePath = "{$basePath}/hls/adaptive.m3u8";
259	            $disk->put($adaptiveRemotePath, $adaptiveContent, [
260	                'visibility' => 'public',
261	                'ContentType' => 'application/vnd.apple.mpegurl',
262	            ]);
263	
264	            MediaVariant::updateOrCreate(
265	                ['media_id' => $mediaId, 'variant_key' => 'adaptive', 'artifact_type' => 'hls_playlist'],
266	                [
267	                    'disk' => $diskName,
268	                    'path' => $adaptiveRemotePath,
269	                    'mime' => 'application/vnd.apple.mpegurl',
270	                ]
271	            );
272	
273	            // Upload poster
274	            $posterRemotePath = "{$basePath}/poster.jpg";
275	            $stream = fopen($tmpPoster, 'rb');
276	            $disk->put($posterRemotePath, $stream, ['visibility' => 'public', 'ContentType' => 'image/jpeg']);
277	            if (is_resource($stream)) {
278	                fclose($stream);
279	            }
280	
281	            MediaVariant::updateOrCreate(
282	                ['media_id' => $mediaId, 'variant_key' => 'poster', 'artifact_type' => 'poster'],
283	                [
284	                    'disk' => $diskName,
285	                    'path' => $posterRemotePath,
286	                    'mime' => 'image/jpeg',
287	                    'file_size_bytes' => filesize($tmpPoster) ?: null,
288	                ]
289	            );
290	
291	            // --- 8. Update SiteMedia ---
292	            SiteMedia::query()
293	                ->where('id', $mediaId)
294	                ->whereNull('deleted_at')
295	                ->update([
296	                    'processing_state' => SiteMedia::PROCESSING_STATE_READY,
297	                    'processing_error' => null,
298	                    'duration_ms' => $durationMs,
299	                    'poster_path' => $posterRemotePath,
300	                ]);
301	
302	            Log::info('VideoVariantService: completed', [
303	                'media_id' => $mediaId,
304	                'duration_ms' => $durationMs,
305	            ]);
306	        } finally {
307	            // Cleanup temp files and dirs
308	            foreach ($mp4Paths ?? [] as $mp4) {
309	                if (file_exists($mp4)) {
310	                    @unlink($mp4);
311	                }
312	            }
313	            if (isset($tmpPoster) && file_exists($tmpPoster)) {
314	                @unlink($tmpPoster);
315	            }
316	            foreach ($tmpDirs as $dir) {
317	                $this->removeDir($dir);
318	            }
319	        }
320	    }
