374	
375	    private function encodeMp4(string $input, string $output, array $def, int $timeout): void
376	    {
377	        $ffmpeg = $this->ffmpegBinary();
378	        $resolution = (string) ($def['resolution'] ?? '1280x720');
379	        [$width, $height] = array_map('intval', explode('x', $resolution, 2));
380	        $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
381	        $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
382	
383	        // Scale to fit within resolution bounds while maintaining aspect ratio.
384	        // The scale filter uses -2 to keep dimensions divisible by 2 (required by libx264).
385	        $scaleFilter = "scale='if(gt(iw,{$width}),{$width},-2)':'if(gt(ih,{$height}),{$height},-2)'";
386	
387	        $cmd = [
388	            $ffmpeg, '-y', '-i', $input,
389	            '-vf', $scaleFilter,
390	            '-c:v', 'libx264',
391	            '-b:v', "{$videoBitrate}k",
392	            '-maxrate', ((int) ($videoBitrate * 1.5)).'k',
393	            '-bufsize', ((int) ($videoBitrate * 2)).'k',
394	            '-profile:v', 'main', '-level', '4.0',
395	            '-movflags', '+faststart',
396	            '-c:a', 'aac', '-b:a', "{$audioBitrate}k", '-ar', '44100',
397	            $output,
398	        ];
399	
400	        $output_str = $this->runCommand($cmd, $exitCode, $timeout);
401	
402	        if ($exitCode !== 0) {
403	            throw new \RuntimeException("ffmpeg MP4 encoding failed (exit {$exitCode}): {$output_str}");
404	        }
405	    }
406	
407	    private function packageHls(string $mp4Input, string $playlistOutput, int $timeout): void
408	    {
409	        $ffmpeg = $this->ffmpegBinary();
410	        $outputDir = dirname($playlistOutput);
411	        $segmentPattern = $outputDir.'/seg_%03d.ts';
412	
413	        $cmd = [
414	            $ffmpeg, '-y', '-i', $mp4Input,
415	            '-c', 'copy', '-f', 'hls',
416	            '-hls_time', '6', '-hls_playlist_type', 'vod',
417	            '-hls_segment_filename', $segmentPattern,
418	            $playlistOutput,
419	        ];
420	
421	        $output = $this->runCommand($cmd, $exitCode, $timeout);
422	
423	        if ($exitCode !== 0) {
424	            throw new \RuntimeException("ffmpeg HLS packaging failed (exit {$exitCode}): {$output}");
425	        }
426	    }
427	
428	    private function extractPoster(string $input, string $output, int $timeout): void
429	    {
430	        $ffmpeg = $this->ffmpegBinary();
431	
432	        $cmd = [$ffmpeg, '-y', '-i', $input, '-ss', '00:00:01', '-frames:v', '1', '-q:v', '3', $output];
433	        $outputStr = $this->runCommand($cmd, $exitCode, $timeout);
434	
435	        if ($exitCode !== 0 || ! file_exists($output)) {
436	            // Non-fatal: try frame at 0s as fallback
437	            $cmd2 = [$ffmpeg, '-y', '-i', $input, '-frames:v', '1', '-q:v', '3', $output];
438	            $this->runCommand($cmd2, $exitCode2, $timeout);
439	
440	            if ($exitCode2 !== 0 || ! file_exists($output)) {
441	                Log::warning('VideoVariantService: could not extract poster frame; writing placeholder JPEG.', [
442	                    'error' => $outputStr,
443	                ]);
444	
445	                if (! $this->writePlaceholderJpeg($output)) {
446	                    throw new \RuntimeException('Could not extract poster frame and GD is unavailable to generate a placeholder.');
447	                }
448	            }
449	        }
450	    }
