452	    /**
453	     * Write a minimal 1×1 black JPEG to $path as a last-resort poster placeholder.
454	     * Returns false if the GD extension is not loaded.
455	     */
456	    private function writePlaceholderJpeg(string $path): bool
457	    {
458	        if (! function_exists('imagecreatetruecolor')) {
459	            return false;
460	        }
461	
462	        $img = imagecreatetruecolor(1, 1);
463	        if ($img === false) {
464	            return false;
465	        }
466	
467	        $written = imagejpeg($img, $path, 85);
468	        imagedestroy($img);
469	
470	        return $written;
471	    }
