473	    /**
474	     * Build the adaptive (master) HLS playlist content.
475	     *
476	     * @param  array<string, array<string, mixed>>  $variantDefs
477	     */
478	    private function buildAdaptivePlaylist(array $variantDefs): string
479	    {
480	        $lines = ['#EXTM3U'];
481	
482	        foreach ($variantDefs as $variantKey => $def) {
483	            // Guard against config values containing newlines or special chars
484	            // that would corrupt the line-based M3U8 format.
485	            if (! preg_match('/^[a-zA-Z0-9_-]+$/', (string) $variantKey)) {
486	                throw new \RuntimeException("Invalid video variant key: {$variantKey}");
487	            }
488	
489	            $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
490	            $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
491	            $bandwidth = ($videoBitrate + $audioBitrate) * 1000;
492	            $resolution = strtoupper((string) ($def['resolution'] ?? '1280x720'));
493	
494	            // Resolution must be WxH (digits only) — e.g. 1280x720, 1920X1080.
495	            if (! preg_match('/^\d+X\d+$/', $resolution)) {
496	                throw new \RuntimeException("Invalid video resolution for variant '{$variantKey}': {$resolution}");
497	            }
498	
499	            $lines[] = "#EXT-X-STREAM-INF:BANDWIDTH={$bandwidth},RESOLUTION={$resolution}";
500	            $lines[] = "{$variantKey}/playlist.m3u8";
501	        }
502	
503	        return implode("\n", $lines)."\n";
504	    }
505	
506	    private function extractDurationMs(array $probe): int
507	    {
508	        $duration = $probe['format']['duration'] ?? null;
509	        if ($duration === null) {
510	            // Fall back to the first video stream
511	            foreach ($probe['streams'] ?? [] as $stream) {
512	                if (($stream['codec_type'] ?? '') === 'video' && isset($stream['duration'])) {
513	                    $duration = $stream['duration'];
514	                    break;
515	                }
516	            }
517	        }
518	
519	        return $duration !== null ? (int) round((float) $duration * 1000) : 0;
520	    }
521	
522	    private function makeTmpFile(string $prefix, string $suffix): string
523	    {
524	        $path = tempnam(sys_get_temp_dir(), $prefix);
525	        if (! $path) {
526	            throw new \RuntimeException("Failed to create temp file ({$prefix}).");
527	        }
528	
529	        // Rename to add the desired extension so FFmpeg knows the container.
530	        $withExt = $path.$suffix;
531	        rename($path, $withExt);
532	
533	        return $withExt;
534	    }
535	
536	    /**
537	     * Run an FFmpeg/FFprobe command via Symfony Process and return combined stdout+stderr.
538	     * $exitCode is set by reference.
539	     *
540	     * Uses array-form Process — each element is passed as a literal argument,
541	     * bypassing the shell entirely and eliminating injection via argument composition.
542	     */
543	    private function runCommand(array $cmd, ?int &$exitCode = null, int $timeout = 30): string
544	    {
545	        $process = new Process($cmd);
546	        $process->setTimeout($timeout);
547	        $process->run();
548	
549	        $exitCode = $process->getExitCode() ?? 0;
550	
551	        return $process->getOutput().$process->getErrorOutput();
552	    }
553	
554	    private function removeDir(string $dir): void
555	    {
556	        if (! is_dir($dir)) {
557	            return;
558	        }
559	
560	        foreach (scandir($dir) ?: [] as $file) {
561	            if ($file === '.' || $file === '..') {
562	                continue;
563	            }
564	            $path = "{$dir}/{$file}";
565	            is_dir($path) ? $this->removeDir($path) : @unlink($path);
566	        }
567	
568	        @rmdir($dir);
569	    }
570	
571	    /**
572	     * Legacy jobs may pass the original file path instead of the media directory.
573	     * Normalize to the directory prefix expected by allFiles().
574	     */
575	    private function normalizeVideoCleanupBasePath(string $basePath): string
576	    {
577	        $normalized = trim($basePath);
578	        if ($normalized === '') {
579	            throw new \RuntimeException('Video cleanup base path cannot be empty.');
580	        }
581	
582	        $leaf = basename($normalized);
583	        if (str_contains($leaf, '.')) {
584	            $normalized = dirname($normalized);
585	        }
586	
587	        $normalized = trim($normalized, '/');
588	        if ($normalized === '' || $normalized === '.') {
589	            throw new \RuntimeException('Video cleanup base path resolved to an invalid directory.');
590	        }
591	
592	        return $normalized;
593	    }
594	
595	    private function diskName(): string
596	    {
597	        $configured = (string) config('partna.media_disk', 'media');
598	
599	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
600	        // but injects platform env vars directly into the process environment at runtime,
601	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
602	        $explicit = $_ENV['PARTNA_MEDIA_DISK'] ?? $_SERVER['PARTNA_MEDIA_DISK']
603	            ?? $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
604	        if (is_string($explicit) && trim($explicit) !== '') {
605	            return $configured;
606	        }
607	
608	        if ($configured === 'media') {
609	            $default = (string) config('filesystems.default', 'local');
610	            $defaultConfig = config("filesystems.disks.{$default}");
611	
612	            if (
613	                $default !== '' &&
614	                $default !== 'local' &&
615	                $default !== 'media' &&
616	                is_array($defaultConfig) &&
617	                (($defaultConfig['driver'] ?? null) === 's3')
618	            ) {
619	                return $default;
620	            }
621	        }
622	
623	        return $configured;
624	    }
625	
626	    private function disk(): \Illuminate\Contracts\Filesystem\Filesystem
627	    {
628	        return Storage::disk($this->diskName());
629	    }
630	
631	    private function ffmpegBinary(): string
632	    {
633	        return (string) config('partna.ffmpeg_binary', 'ffmpeg');
634	    }
635	
636	    private function ffprobeBinary(): string
637	    {
638	        return (string) config('partna.ffprobe_binary', 'ffprobe');
639	    }
